mapper.select:
/* com.heeji.picket.repository.ShowReviewsRepository.list */
SELECT  *
FROM    SHOW_REVIEWS
WHERE   1 = 1
AND     SHOW_ID = #{showId}

mapper.delete:
/* com.heeji.picket.repository.ShowReviewsRepository.delete */
DELETE FROM SHOW_REVIEWS
WHERE       1 = 1
AND         LIKE_ID = #{likeId}
